import { Duration, Effect, Layer, Schedule, Schema, Semaphore, Context, Stream } from "effect"
import { ChildProcess, ChildProcessSpawner } from "effect/unstable/process"
import { createPatch, diffStats } from "@/util/diff-wasm"
import path from "path"
import type { Dirent } from "fs"
import * as NodeFs from "fs/promises"
import z from "zod"
import { CrossSpawnSpawner } from "@opencode-ai/core/cross-spawn-spawner"
import { InstanceState } from "@/effect/instance-state"
import { AppFileSystem } from "@opencode-ai/core/filesystem"
import { Hash } from "@opencode-ai/core/util/hash"
import { Config } from "@/config/config"
import { Global } from "@opencode-ai/core/global"
import * as Log from "@opencode-ai/core/util/log"
import { withStatics } from "@/util/schema"
import { zod } from "@/util/effect-zod"

export const Patch = Schema.Struct({
  hash: Schema.String,
  files: Schema.mutable(Schema.Array(Schema.String)),
}).pipe(withStatics((s) => ({ zod: zod(s) })))
export type Patch = typeof Patch.Type

export const FileDiff = Schema.Struct({
  file: Schema.String,
  patch: Schema.String,
  additions: Schema.Number,
  deletions: Schema.Number,
  status: Schema.optional(Schema.Literals(["added", "deleted", "modified"])),
})
  .annotate({ identifier: "SnapshotFileDiff" })
  .pipe(withStatics((s) => ({ zod: zod(s) })))
export type FileDiff = typeof FileDiff.Type

const log = Log.create({ service: "snapshot" })
const prune = Duration.toMillis(Duration.days(7))
const limit = 2 * 1024 * 1024

interface GitResult {
  readonly code: ChildProcessSpawner.ExitCode
  readonly text: string
  readonly stderr: string
}

interface SnapshotEntry {
  readonly path: string
  readonly kind: "file" | "symlink"
  readonly hash?: string
  readonly size?: number
  readonly link?: string
  readonly linkType?: "file" | "dir"
}

interface SnapshotManifest {
  readonly version: 1
  readonly worktree: string
  readonly entries: readonly SnapshotEntry[]
}

type State = Omit<Interface, "init">

export interface Interface {
  readonly init: () => Effect.Effect<void>
  readonly cleanup: () => Effect.Effect<void>
  readonly track: () => Effect.Effect<string | undefined>
  readonly patch: (hash: string) => Effect.Effect<Patch>
  readonly restore: (snapshot: string) => Effect.Effect<void>
  readonly revert: (patches: Patch[]) => Effect.Effect<void>
  readonly diff: (hash: string) => Effect.Effect<string>
  readonly diffFull: (from: string, to: string) => Effect.Effect<FileDiff[]>
}

export class Service extends Context.Service<Service, Interface>()("@opencode/Snapshot") {}

export const layer: Layer.Layer<
  Service,
  never,
  AppFileSystem.Service | ChildProcessSpawner.ChildProcessSpawner | Config.Service
> = Layer.effect(
  Service,
  Effect.gen(function* () {
    const fs = yield* AppFileSystem.Service
    const spawner = yield* ChildProcessSpawner.ChildProcessSpawner
    const config = yield* Config.Service
    const locks = new Map<string, Semaphore.Semaphore>()

    const lock = (key: string) => {
      const hit = locks.get(key)
      if (hit) return hit
      const next = Semaphore.makeUnsafe(1)
      locks.set(key, next)
      return next
    }

    const state = yield* InstanceState.make<State>(
      Effect.fn("Snapshot.state")(function* (ctx) {
        const state = {
          directory: ctx.directory,
          worktree: ctx.worktree,
          store: path.join(Global.Path.data, "snapshot", ctx.project.id, Hash.fast(ctx.worktree)),
          vcs: ctx.project.vcs,
        }

        const objects = path.join(state.store, "objects")
        const snapshots = path.join(state.store, "snapshots")
        const enc = new TextEncoder()
        const feed = (list: string[]) => Stream.make(enc.encode(list.join("\0") + "\0"))
        const slash = (value: string) => value.replaceAll("\\", "/")
        const absolute = (rel: string) => slash(path.join(state.worktree, rel))
        const locked = <A, E, R>(fx: Effect.Effect<A, E, R>) => lock(state.store).withPermits(1)(fx)
        const exists = (file: string) => fs.exists(file).pipe(Effect.orElseSucceed(() => false))
        const remove = (file: string) => fs.remove(file, { recursive: true, force: true }).pipe(Effect.catch(() => Effect.void))

        const git = Effect.fnUntraced(
          function* (cmd: string[], opts?: { stdin?: ChildProcess.CommandInput }) {
            const proc = ChildProcess.make("git", ["-C", state.worktree, "-c", "core.quotepath=false", ...cmd], {
              cwd: state.directory,
              extendEnv: true,
              stdin: opts?.stdin,
            })
            const handle = yield* spawner.spawn(proc)
            const [text, stderr] = yield* Effect.all(
              [Stream.mkString(Stream.decodeText(handle.stdout)), Stream.mkString(Stream.decodeText(handle.stderr))],
              { concurrency: 2 },
            )
            const code = yield* handle.exitCode
            return { code, text, stderr } satisfies GitResult
          },
          Effect.scoped,
          Effect.catch((err) =>
            Effect.succeed({
              code: ChildProcessSpawner.ExitCode(1),
              text: "",
              stderr: err instanceof Error ? err.message : String(err),
            }),
          ),
        )

        const enabled = Effect.fnUntraced(function* () {
          if (state.vcs !== "git") return false
          return (yield* config.get()).snapshot !== false
        })

        const listCandidates = Effect.fnUntraced(function* () {
          const [tracked, other] = yield* Effect.all(
            [
              git(["ls-files", "-z", "--cached", "--", "."]),
              git(["ls-files", "-z", "--others", "--exclude-standard", "--", "."]),
            ],
            { concurrency: 2 },
          )
          if (tracked.code !== 0 || other.code !== 0) {
            log.warn("failed to list snapshot files", {
              trackedCode: tracked.code,
              trackedStderr: tracked.stderr,
              otherCode: other.code,
              otherStderr: other.stderr,
            })
            return { files: [] as string[], untracked: new Set<string>() }
          }

          const untracked = new Set(other.text.split("\0").filter(Boolean).map(slash))
          const files = Array.from(new Set([...tracked.text.split("\0"), ...untracked].filter(Boolean).map(slash))).filter(
            (item) => item !== ".jj" && !item.startsWith(".jj/"),
          )
          if (!files.length) return { files, untracked }

          const ignored = yield* git(["check-ignore", "--no-index", "--stdin", "-z"], { stdin: feed(files) })
          if (ignored.code !== 0 && ignored.code !== 1) return { files, untracked }
          const ignoredSet = new Set(ignored.text.split("\0").filter(Boolean).map(slash))
          return {
            files: files.filter((item) => !ignoredSet.has(item)),
            untracked,
          }
        })

        const objectPath = (hash: string) => path.join(objects, hash.slice(0, 2), hash)

        const writeObject = Effect.fnUntraced(function* (bytes: Uint8Array) {
          const hash = Hash.fast(Buffer.from(bytes))
          const target = objectPath(hash)
          if (!(yield* exists(target))) {
            yield* fs.ensureDir(path.dirname(target)).pipe(Effect.orDie)
            yield* fs.writeFile(target, bytes).pipe(Effect.orDie)
          }
          return hash
        })

        const readObject = Effect.fnUntraced(function* (hash: string) {
          return yield* fs.readFile(objectPath(hash)).pipe(Effect.orElseSucceed(() => new Uint8Array()))
        })

        const ensureParent = Effect.fnUntraced(function* (dir: string) {
          if (dir === state.worktree || dir === path.dirname(dir)) return
          const stat = yield* Effect.tryPromise(() => NodeFs.lstat(dir)).pipe(Effect.catch(() => Effect.succeed(undefined)))
          if (stat?.isDirectory()) return
          if (stat) yield* remove(dir)
          yield* ensureParent(path.dirname(dir))
          yield* fs.ensureDir(dir).pipe(Effect.orDie)
        })

        const readManifest = Effect.fnUntraced(function* (hash: string) {
          const file = path.join(snapshots, `${hash}.json`)
          const raw = yield* fs.readFileString(file).pipe(Effect.catch(() => Effect.succeed("")))
          if (!raw) return
          const parsed = JSON.parse(raw) as Partial<SnapshotManifest>
          if (parsed.version !== 1 || !Array.isArray(parsed.entries)) return
          return {
            version: 1,
            worktree: typeof parsed.worktree === "string" ? parsed.worktree : state.worktree,
            entries: parsed.entries
              .flatMap((entry) => {
                if (!entry || typeof entry.path !== "string") return []
                if (entry.kind === "file" && typeof entry.hash === "string") return [entry as SnapshotEntry]
                if (entry.kind === "symlink" && typeof entry.link === "string") return [entry as SnapshotEntry]
                return []
              })
              .sort((a, b) => a.path.localeCompare(b.path)),
          } satisfies SnapshotManifest
        })

        const scan = Effect.fnUntraced(function* () {
          const candidates = yield* listCandidates()
          const entries = yield* Effect.all(
            candidates.files.map((rel) =>
              Effect.gen(function* () {
                const full = path.join(state.worktree, rel)
                const stat = yield* Effect.tryPromise(() => NodeFs.lstat(full)).pipe(Effect.catch(() => Effect.succeed(undefined)))
                if (!stat) return
                if (stat.isDirectory()) return
                if (stat.isSymbolicLink()) {
                  const link = yield* Effect.tryPromise(() => NodeFs.readlink(full)).pipe(Effect.catch(() => Effect.succeed("")))
                  if (!link) return
                  const target = yield* Effect.tryPromise(() => NodeFs.stat(full)).pipe(Effect.catch(() => Effect.succeed(undefined)))
                  return {
                    path: rel,
                    kind: "symlink",
                    link,
                    linkType: target?.isDirectory() ? "dir" : "file",
                  } satisfies SnapshotEntry
                }
                if (!stat.isFile()) return
                if (candidates.untracked.has(rel) && stat.size > limit) return
                const bytes = yield* fs.readFile(full).pipe(Effect.catch(() => Effect.succeed(new Uint8Array())))
                return {
                  path: rel,
                  kind: "file",
                  hash: yield* writeObject(bytes),
                  size: bytes.length,
                } satisfies SnapshotEntry
              }),
            ),
            { concurrency: 8 },
          )
          return entries.filter((entry): entry is SnapshotEntry => Boolean(entry)).sort((a, b) => a.path.localeCompare(b.path))
        })

        const hashManifest = (manifest: SnapshotManifest) =>
          Hash.fast(JSON.stringify({ version: manifest.version, entries: manifest.entries }))

        const writeManifest = Effect.fnUntraced(function* (manifest: SnapshotManifest) {
          const hash = hashManifest(manifest)
          yield* fs.ensureDir(snapshots).pipe(Effect.orDie)
          yield* fs.writeFileString(path.join(snapshots, `${hash}.json`), JSON.stringify(manifest, null, 2)).pipe(Effect.orDie)
          return hash
        })

        const entryMap = (manifest: SnapshotManifest) => new Map(manifest.entries.map((entry) => [entry.path, entry]))

        const changed = (before: SnapshotEntry | undefined, after: SnapshotEntry | undefined) => {
          if (!before && after) return true
          if (before && !after) return true
          if (!before || !after) return false
          if (before.kind !== after.kind) return true
          if (before.kind === "file") return before.hash !== after.hash
          return before.link !== after.link || before.linkType !== after.linkType
        }

        const compare = (before: SnapshotManifest, after: SnapshotManifest) => {
          const left = entryMap(before)
          const right = entryMap(after)
          return Array.from(new Set([...left.keys(), ...right.keys()]))
            .sort((a, b) => a.localeCompare(b))
            .flatMap((file) => (changed(left.get(file), right.get(file)) ? [{ file, before: left.get(file), after: right.get(file) }] : []))
        }

        const currentManifest = Effect.fnUntraced(function* () {
          return {
            version: 1,
            worktree: state.worktree,
            entries: yield* scan(),
          } satisfies SnapshotManifest
        })

        const restoreEntry = Effect.fnUntraced(function* (entry: SnapshotEntry) {
          const full = path.join(state.worktree, entry.path)
          yield* ensureParent(path.dirname(full))
          if (entry.kind === "symlink") {
            yield* remove(full)
            yield* Effect.tryPromise(() => NodeFs.symlink(entry.link ?? "", full, entry.linkType === "dir" ? "dir" : "file")).pipe(
              Effect.catch((err) => {
                log.warn("failed to restore symlink snapshot entry", { file: full, error: String(err) })
                return Effect.void
              }),
            )
            return
          }
          const stat = yield* Effect.tryPromise(() => NodeFs.lstat(full)).pipe(Effect.catch(() => Effect.succeed(undefined)))
          if (stat && !stat.isFile()) yield* remove(full)
          yield* fs.writeWithDirs(full, yield* readObject(entry.hash ?? "")).pipe(Effect.orDie)
        })

        const entryText = Effect.fnUntraced(function* (entry: SnapshotEntry | undefined) {
          if (!entry) return ""
          if (entry.kind === "symlink") return entry.link ?? ""
          const bytes = yield* readObject(entry.hash ?? "")
          if (bytes.includes(0)) return
          return yield* Effect.try({
            try: () => new TextDecoder("utf-8", { fatal: true }).decode(bytes),
            catch: () => undefined,
          })
        })

        const fileDiff = Effect.fnUntraced(function* (file: string, before: SnapshotEntry | undefined, after: SnapshotEntry | undefined) {
          const status = !before ? "added" : !after ? "deleted" : "modified"
          const oldText = yield* entryText(before)
          const newText = yield* entryText(after)
          if (oldText === undefined || newText === undefined) {
            return { file, patch: "", additions: 0, deletions: 0, status } satisfies FileDiff
          }
          const stats = (yield* Effect.promise(() => diffStats(oldText, newText))) ?? { additions: 0, deletions: 0 }
          return {
            file,
            patch: (yield* Effect.promise(() => createPatch(oldText, newText))) ?? "",
            additions: stats.additions,
            deletions: stats.deletions,
            status,
          } satisfies FileDiff
        })

        const cleanup = Effect.fnUntraced(function* () {
          return yield* locked(
            Effect.gen(function* () {
              if (!(yield* enabled())) return
              if (!(yield* exists(snapshots))) return
              const now = Date.now()
              const entries = yield* Effect.tryPromise(() => NodeFs.readdir(snapshots, { withFileTypes: true })).pipe(
                Effect.catch(() => Effect.succeed([] as Dirent[])),
              )
              yield* Effect.all(
                entries
                  .filter((entry) => entry.isFile() && entry.name.endsWith(".json"))
                  .map((entry) =>
                    Effect.gen(function* () {
                      const file = path.join(snapshots, entry.name)
                      const stat = yield* Effect.tryPromise(() => NodeFs.stat(file)).pipe(Effect.catch(() => Effect.succeed(undefined)))
                      if (stat && now - stat.mtimeMs > prune) yield* remove(file)
                    }),
                  ),
                { concurrency: 8 },
              )
            }),
          )
        })

        const track = Effect.fnUntraced(function* () {
          return yield* locked(
            Effect.gen(function* () {
              if (!(yield* enabled())) return
              const hash = yield* writeManifest(yield* currentManifest())
              log.info("tracking", { hash, store: state.store })
              return hash
            }),
          )
        })

        const patch = Effect.fnUntraced(function* (hash: string) {
          return yield* locked(
            Effect.gen(function* () {
              const before = yield* readManifest(hash)
              if (!before) return { hash, files: [] }
              const after = yield* currentManifest()
              return {
                hash,
                files: compare(before, after).map((item) => absolute(item.file)),
              }
            }),
          )
        })

        const restore = Effect.fnUntraced(function* (snapshot: string) {
          return yield* locked(
            Effect.gen(function* () {
              log.info("restore", { snapshot })
              const manifest = yield* readManifest(snapshot)
              if (!manifest) return
              for (const entry of manifest.entries) yield* restoreEntry(entry)
            }),
          )
        })

        const revert = Effect.fnUntraced(function* (patches: Patch[]) {
          return yield* locked(
            Effect.gen(function* () {
              const ops: { hash: string; file: string; rel: string }[] = []
              const seen = new Set<string>()
              for (const item of patches) {
                for (const file of item.files) {
                  if (seen.has(file)) continue
                  seen.add(file)
                  ops.push({
                    hash: item.hash,
                    file,
                    rel: slash(path.relative(state.worktree, file)),
                  })
                }
              }

              for (const op of ops) {
                const manifest = yield* readManifest(op.hash)
                const entry = manifest ? entryMap(manifest).get(op.rel) : undefined
                log.info("reverting", { file: op.file, hash: op.hash })
                if (entry) {
                  yield* restoreEntry(entry)
                  continue
                }
                yield* remove(op.file)
              }
            }),
          )
        })

        const diff = Effect.fnUntraced(function* (hash: string) {
          return yield* locked(
            Effect.gen(function* () {
              const before = yield* readManifest(hash)
              if (!before) return ""
              const after = yield* currentManifest()
              const rows = compare(before, after)
              const diffs = yield* Effect.all(rows.map((row) => fileDiff(row.file, row.before, row.after)), { concurrency: 4 })
              return diffs
                .map((item) => item.patch || (item.status ? `diff --git a/${item.file} b/${item.file}\n` : ""))
                .filter(Boolean)
                .join("\n")
                .trim()
            }),
          )
        })

        const diffFull = Effect.fnUntraced(function* (from: string, to: string) {
          return yield* locked(
            Effect.gen(function* () {
              const before = yield* readManifest(from)
              const after = yield* readManifest(to)
              if (!before || !after) return [] as FileDiff[]
              return yield* Effect.all(
                compare(before, after).map((row) => fileDiff(row.file, row.before, row.after)),
                { concurrency: 4 },
              )
            }),
          )
        })

        yield* cleanup().pipe(
          Effect.catch(() => Effect.void),
          Effect.repeat(Schedule.spaced(Duration.hours(1))),
          Effect.delay(Duration.minutes(1)),
          Effect.forkScoped,
        )

        return { cleanup, track, patch, restore, revert, diff, diffFull }
      }),
    )

    return Service.of({
      init: Effect.fn("Snapshot.init")(function* () {
        yield* InstanceState.get(state)
      }),
      cleanup: Effect.fn("Snapshot.cleanup")(function* () {
        return yield* InstanceState.useEffect(state, (s) => s.cleanup())
      }),
      track: Effect.fn("Snapshot.track")(function* () {
        return yield* InstanceState.useEffect(state, (s) => s.track())
      }),
      patch: Effect.fn("Snapshot.patch")(function* (hash: string) {
        return yield* InstanceState.useEffect(state, (s) => s.patch(hash))
      }),
      restore: Effect.fn("Snapshot.restore")(function* (snapshot: string) {
        return yield* InstanceState.useEffect(state, (s) => s.restore(snapshot))
      }),
      revert: Effect.fn("Snapshot.revert")(function* (patches: Patch[]) {
        return yield* InstanceState.useEffect(state, (s) => s.revert(patches))
      }),
      diff: Effect.fn("Snapshot.diff")(function* (hash: string) {
        return yield* InstanceState.useEffect(state, (s) => s.diff(hash))
      }),
      diffFull: Effect.fn("Snapshot.diffFull")(function* (from: string, to: string) {
        return yield* InstanceState.useEffect(state, (s) => s.diffFull(from, to))
      }),
    })
  }),
)

export const defaultLayer = layer.pipe(
  Layer.provide(CrossSpawnSpawner.defaultLayer),
  Layer.provide(AppFileSystem.defaultLayer),
  Layer.provide(Config.defaultLayer),
)

export * as Snapshot from "."
